/* ============================================================
   VERIFICARE PROIECT v2 — evaluator ghidat, determinist, client-side.
   - Reguli PRE-ÎNCĂRCATE: din radar (apel verificat la sursă) + reguli
     universale cu bază legală (Reg. 651/2014, 2023/2831, checklist CAE).
   - Dosar ghidat: întrebări Da/Nu/Nu știu + câmpuri, precompletate din CRM.
   - Semafor LIVE: verdictul se recalculează la fiecare modificare.
   - Raport: plan de acțiune, reguli aplicate cu sursă, salvare la proiect,
     PDF (print), export JSON, rezumat pentru client.
   Trei stări per regulă: CONFORM · NECONFORM · NU SE POATE VERIFICA.
   AI pregătește; omul decide. Documentele rămân în browser.
   ============================================================ */
"use strict";
window.EVAL = window.EVAL || { rb:{} };
const EV_LS="eufcc_rulebooks";
function evLoad(){ try{ const s=localStorage.getItem(EV_LS); if(s) window.EVAL.rb=JSON.parse(s)||{}; }catch(e){} }
function evSave(){ try{ localStorage.setItem(EV_LS, JSON.stringify(window.EVAL.rb)); }catch(e){} }
function evList(){ return Object.values(window.EVAL.rb); }
function evId(){ return "rb_"+Date.now().toString(36)+"_"+Math.floor(Math.random()*1e4); }
const EV_CURS=(function(){ try{ const c=(DB.verificari||{}).curs||{}; return {ron:c.ron||5.2418,label:(c.sursa||"InforEuro")+(c.luna?" · "+c.luna:"")}; }catch(e){ return {ron:5.2418,label:"InforEuro"}; } })();
function evTodayIso(){ const d=TODAY; return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
function evEmptyDosar(){ return { client_id:"", project_id:"", solicitant:{}, financiar:{ cheltuieli:[], moneda:"lei", curs:EV_CURS.ron }, documente_prezente:[], concordanta:{ indicatori:[] }, raspunsuri:{}, data_depunere:evTodayIso(), data_onrc:"" }; }
window.evUI = window.evUI || { curId:null, step:0, dosar:evEmptyDosar() };
function evSaveUI(){ try{ localStorage.setItem("eufcc_evui",JSON.stringify({curId:window.evUI.curId,step:window.evUI.step,dosar:window.evUI.dosar})); }catch(e){} }
function evLoadUI(){ if(window.evUI._restored) return; window.evUI._restored=true; try{ const o=JSON.parse(localStorage.getItem("eufcc_evui")||"null"); if(o&&o.dosar){ window.evUI.dosar=Object.assign(evEmptyDosar(),o.dosar); if(o.curId&&window.EVAL.rb[o.curId]) window.evUI.curId=o.curId; if(o.step!=null) window.evUI.step=o.step; } }catch(e){} }

/* ---- comparatoare & utilitare deterministe ---- */
function evCmp(op,a,b){ const na=parseFloat(a), nb=parseFloat(b); const bothNum=!isNaN(na)&&!isNaN(nb);
  switch(op){ case "ge": return bothNum?na>=nb:null; case "le": return bothNum?na<=nb:null; case "gt": return bothNum?na>nb:null; case "lt": return bothNum?na<nb:null;
    case "eq": return bothNum?na===nb:String(a).trim().toLowerCase()===String(b).trim().toLowerCase();
    case "ne": return bothNum?na!==nb:String(a).trim().toLowerCase()!==String(b).trim().toLowerCase();
    case "in": { const fa=String(a).trim().toLowerCase(); const l=String(b).split(/[,;/]/).map(x=>x.trim().toLowerCase()).filter(Boolean); return l.some(t=>t===fa||fa.includes(t)||t.includes(fa)); }
    case "nin": { const fa=String(a).trim().toLowerCase(); const l=String(b).split(/[,;/]/).map(x=>x.trim().toLowerCase()).filter(Boolean); return !l.some(t=>t===fa||fa.includes(t)||t.includes(fa)); } }
  return null; }
const EV_OPLBL={ge:"≥",le:"≤",gt:">",lt:"<",eq:"=",ne:"≠",in:"∈ (în lista)",nin:"∉ (nu în lista)"};
const EV_FACTFIELDS=[["dimensiune","Dimensiune (micro/mica/mijlocie/mare)"],["tip","Tip solicitant"],["regiune","Regiune"],["judet","Județ"],["vechime_ani","Vechime (ani)"],["caen","CAEN"],["capitaluri_proprii_lei","Capitaluri proprii (lei)"],["nr_angajati","Nr. angajați"],["cifra_afaceri_lei","Cifră de afaceri (lei)"]];
function evNum(v){ if(v==null||v==="") return null; let s=String(v).trim().replace(/[^0-9.,\-]/g,""); if(s.indexOf(",")>=0&&s.indexOf(".")>=0){ s=s.replace(/\./g,"").replace(",","."); } else if(s.indexOf(",")>=0){ s=s.replace(",","."); } const n=parseFloat(s); return isNaN(n)?null:n; }
const EV_DIMS=["microintreprindere","mica","mijlocie","mare"];
function evImmCalc(ang,caEur){ if(ang==null&&caEur==null) return null; if((ang!=null&&ang>=250)||(caEur!=null&&caEur>50e6)) return "mare"; if((ang!=null&&ang>=50)||(caEur!=null&&caEur>10e6)) return "mijlocie"; if((ang!=null&&ang>=10)||(caEur!=null&&caEur>2e6)) return "mica"; return "microintreprindere"; }
const EV_BENMAP={ microintreprindere:s=>!["UAT","ONG","institutie_publica","universitate"].includes(s.tip)&&s.dimensiune==="microintreprindere", IMM:s=>!["UAT","ONG","institutie_publica","universitate"].includes(s.tip)&&["microintreprindere","mica","mijlocie"].includes(s.dimensiune), intreprindere_mare:s=>s.dimensiune==="mare", UAT:s=>s.tip==="UAT", ONG:s=>s.tip==="ONG", fermier:s=>s.tip==="fermier"||s.tip==="PFA", PFA:s=>s.tip==="PFA", institutie_publica:s=>s.tip==="institutie_publica"||s.tip==="UAT", universitate:s=>s.tip==="universitate", persoana_fizica:s=>s.tip==="persoana_fizica" };
const EV_TIPURI=[["privat","Firmă privată"],["UAT","UAT (primărie / CJ)"],["ONG","ONG / asociație"],["fermier","Fermier"],["PFA","PFA / II"],["institutie_publica","Instituție publică"],["universitate","Universitate / CDI"]];
const EV_DOCS_PRIVAT=["Cerere de finanțare (MySMIS)","Declarația unică (semnată de reprezentantul legal)","Certificat constatator ONRC (≤30 zile)","Situații financiare — ultimul exercițiu încheiat","Certificate de atestare fiscală (buget de stat + local)","Documente privind imobilul / locația de implementare","Plan de afaceri / studiu (după caz)","Bugetul proiectului + devize / oferte","Declarație privind încadrarea în categoria IMM","Declarație ajutoare de minimis / de stat (după caz)"];
const EV_DOCS_UAT=["Cerere de finanțare (MySMIS)","HCL de aprobare a proiectului și a cheltuielilor","Studiu de fezabilitate / DALI (HG 907/2016)","Certificat de urbanism","Dovada proprietății / administrării imobilului","Declarația de angajament pentru cofinanțare","Aviz / decizie de mediu (după caz)","Analiza cost-beneficiu (după caz)"];
const EV_CHELT_TIPICE=["Construcții / amenajări","Echipamente și utilaje","Echipamente IT & software","Mobilier","Consultanță","Proiectare / asistență tehnică","Publicitate / informare","Instruire","Cheltuieli salariale","TVA","Alte cheltuieli"];

/* ---- rulebook pre-încărcat din apelul din radar ---- */
function evDetectAjutor(a){ const t=((a.tip_ajutor||"")+" "+(a.note||"")+" "+(a.titlu||"")).toLowerCase(); if(/minimis/.test(t)) return "minimis"; if(/ajutor de stat|gber|ajutor regional|schem[ăa] de ajutor/.test(t)) return "stat"; return ""; }
function evSeedFromApel(apelId){ const a=apelById(apelId)||{}; const has=!!a.id_apel;
  const conf=(a.incredere_extractie==null||a.incredere_extractie>=0.8);
  const tb=a.tip_beneficiar||[]; const priv=tb.some(b=>/micro|IMM|intreprindere|PFA|fermier/.test(b)); const pub=tb.some(b=>/UAT|institutie/.test(b));
  const ta=evDetectAjutor(a); const leg=[]; if(ta==="minimis") leg.push("minimis"); if(ta==="stat") leg.push("regional"); if(priv||!has) leg.push("dificultate","imm");
  const docs=(priv||!has?EV_DOCS_PRIVAT:pub?EV_DOCS_UAT:[]).map(d=>({nume:d,forma:"",confirmat:false,sursa:"listă tipică pre-CAE — confirmă în ghid"}));
  return { id:evId(), apel_id:has?apelId:"", titlu:has?(a.titlu||"Apel"):"Verificare generală (fără apel)", program:a.program||"", versiune:2, activ:true, auto:has, auto_conf:conf,
    eligibilitate:[], financiar:{ sprijin_min:a.grant_min!=null?a.grant_min:null, sprijin_max:a.grant_max!=null?a.grant_max:null, intensitate_max_pct:a.intensitate_max_pct!=null?a.intensitate_max_pct:null, tip_ajutor:ta, moneda:a.moneda||"EUR", plafoane:[], neeligibile:[], confirmat:true, sursa:has?"radar (verificat la sursă)":"manual" },
    documente:docs, grila:{ prag_minim:null, criterii:(a.criterii_cheie||[]).slice(0,8).map(c=>({nume:c,punctaj_max:null,tip:"subiectiv",eliminatoriu:false,sursa:"criterii_cheie din radar",confirmat:false})) },
    legislatie:leg, termene:{ depunere:a.data_inchidere||"" }, creat:evTodayIso() }; }
function evRbForApel(apelId){ const ex=evList().find(r=>r.apel_id===apelId); if(ex) return ex; const rb=evSeedFromApel(apelId); window.EVAL.rb[rb.id]=rb; evSave(); return rb; }

/* ============ MOTORUL ============ */
function evEvaluate(rb, f){
  const checks=[]; const add=o=>checks.push(Object.assign({status:"NV",blocant:false},o));
  const sol=f.solicitant||{}, fin=f.financiar||{}, R=f.raspunsuri||{}; const a=rb.apel_id?(apelById(rb.apel_id)||{}):{};
  const curs=evNum(fin.curs)||EV_CURS.ron; const dm=fin.moneda||"lei";
  const toEUR=v=>v==null?null:(dm==="EUR"?v:v/curs); const toRb=v=>{ if(v==null) return null; const rm=(rb.financiar||{}).moneda||"EUR"; if(rm===dm) return v; if(/EUR/i.test(rm)) return toEUR(v); return dm==="EUR"?v*curs:v; };
  const val=evNum(fin.valoare_proiect), spr=evNum(fin.sprijin_solicitat); const cofIn=evNum(fin.cofinantare); const cof=cofIn!=null?cofIn:(val!=null&&spr!=null?val-spr:null);
  const it=(val&&spr)?Math.round(spr/val*1000)/10:null;
  const reg=sol.judet?onrcRegOf(sol.judet):""; const regiune=reg||sol.regiune||"";
  const dep=f.data_depunere||evTodayIso(); const dz=s=>{ const d=pd(s), e=pd(dep); return (d&&e)?Math.round((d-e)/86400000):null; };
  const ans=k=>R[k]||"ns";
  const srcRadar=rb.auto_conf===false?"radar — apel marcat [DE VERIFICAT]":"radar (apel verificat la sursă)";

  /* ---- 0. Apelul: fereastră, stare, beneficiari, teritoriu ---- */
  if(a.id_apel){
    if(a.stare==="inchis") add({strat:"Apel",titlu:"Apelul este închis",status:"NECONFORM",blocant:true,gasit:"închis",cerut:"deschis la data depunerii",sursa:srcRadar,fix:"Apelul s-a închis. Caută următoarea sesiune sau un apel echivalent în Radar.",unde:"sec-ctx"});
    else if(a.stare==="consultare") add({strat:"Apel",titlu:"Ghid în consultare publică",status:"NV",sursa:srcRadar,fix:"Regulile pot fi modificate până la publicarea ghidului final — reia verificarea după lansare.",unde:"sec-ctx"});
    else if(a.stare==="planificat"){ const dd=a.data_deschidere?dz(a.data_deschidere):null; add({strat:"Apel",titlu:"Apelul nu este încă deschis",status:"NECONFORM",blocant:false,gasit:a.data_deschidere?"se deschide "+fmtD(a.data_deschidere)+(dd!=null?" (în "+dd+" zile)":""):"dată de deschidere nepublicată",cerut:"depunere după deschidere",sursa:srcRadar,fix:"Pregătește dosarul acum; depunerea e posibilă doar după deschidere.",unde:"sec-ctx"}); }
    if(a.data_inchidere){ const d=dz(a.data_inchidere);
      if(d<0) add({strat:"Apel",titlu:"Termenul de depunere a trecut",status:"NECONFORM",blocant:true,gasit:fmtD(a.data_inchidere),cerut:"depunere până la termen",sursa:srcRadar,fix:"Termenul ("+fmtD(a.data_inchidere)+") e anterior datei de depunere planificate.",unde:"sec-ctx"});
      else if(d<=7) add({strat:"Apel",titlu:"Termen foarte apropiat",status:"NECONFORM",blocant:false,gasit:d+" zile până la "+fmtD(a.data_inchidere),cerut:"marjă de siguranță ≥7 zile",sursa:srcRadar+" · prag intern",fix:"Risc de dosar incomplet: listă de documente cu responsabili pe zile, depunere cu cel puțin 48h înainte.",unde:"sec-ctx"});
      else add({strat:"Apel",titlu:"Fereastra de depunere",status:"CONFORM",gasit:d+" zile până la "+fmtD(a.data_inchidere),cerut:"deschis",sursa:srcRadar}); }
    else if(/continu/i.test(a.tip_depunere||"")) add({strat:"Apel",titlu:"Depunere continuă",status:"CONFORM",gasit:"până la epuizarea fondurilor",cerut:"—",sursa:srcRadar});
    const tb=a.tip_beneficiar||[];
    if(tb.length){ if(!sol.tip&&!sol.dimensiune) add({strat:"Eligibilitate",titlu:"Tipul de beneficiar eligibil",status:"NV",cerut:tb.map(b=>BEN[b]||b).join(" / "),sursa:srcRadar,fix:"Completează tipul și dimensiunea solicitantului.",unde:"sec-sol"});
      else { const ok=tb.some(b=>{ const fn=EV_BENMAP[b]; return fn?fn(sol):false; }); const gasit=(EV_TIPURI.find(t=>t[0]===sol.tip)||[])[1]||sol.tip||"—"; add({strat:"Eligibilitate",titlu:"Tipul de beneficiar eligibil",status:ok?"CONFORM":"NECONFORM",blocant:!ok,gasit:gasit+(sol.dimensiune?" · "+sol.dimensiune:""),cerut:tb.map(b=>BEN[b]||b).join(" / "),sursa:srcRadar,fix:ok?"":"Solicitantul nu se încadrează în categoriile de beneficiari ale apelului. Verifică ghidul (cap. Solicitanți eligibili) — dacă radarul e incomplet, adaugă categoria în reguli.",unde:"sec-sol"}); } }
    const rs=a.regiuni||[]; const jud=a.judete_eligibile||[];
    if(jud.length){ if(!sol.judet) add({strat:"Eligibilitate",titlu:"Județ eligibil",status:"NV",cerut:jud.join(", "),sursa:srcRadar,fix:"Completează județul locației de implementare.",unde:"sec-sol"}); else { const ok=jud.some(j=>onrcNorm(j)===onrcNorm(sol.judet)); add({strat:"Eligibilitate",titlu:"Județ eligibil",status:ok?"CONFORM":"NECONFORM",blocant:!ok,gasit:sol.judet,cerut:jud.join(", "),sursa:srcRadar,fix:ok?"":"Locația de implementare nu e într-un județ eligibil pentru acest apel.",unde:"sec-sol"}); } }
    else if(rs.length&&!rs.includes("Național")){ if(!regiune) add({strat:"Eligibilitate",titlu:"Regiune eligibilă",status:"NV",cerut:rs.join(", "),sursa:srcRadar,fix:"Completează județul (regiunea se deduce automat).",unde:"sec-sol"}); else { const ok=rs.some(r=>onrcNorm(r)===onrcNorm(regiune))||(rs.includes("ITI")&&/tulcea|constan/i.test(sol.judet||"")); add({strat:"Eligibilitate",titlu:"Regiune eligibilă",status:ok?"CONFORM":"NECONFORM",blocant:!ok,gasit:regiune+(sol.judet?" ("+sol.judet+")":""),cerut:rs.join(", "),sursa:srcRadar,fix:ok?"":"Regiunea locației de implementare nu e acoperită de apel. Caută apelul echivalent al PR-ului din regiunea ta.",unde:"sec-sol"}); } }
  }

  /* ---- A. Financiar (plafoane din radar/ghid) ---- */
  const fi=rb.financiar||{}; const rm=fi.moneda||"EUR"; const sprR=toRb(spr); const fmtR=v=>nf.format(Math.round(v))+" "+rm;
  if(fi.confirmat!==false){
    if(fi.sprijin_max!=null){ if(sprR==null) add({strat:"Financiar",titlu:"Sprijin ≤ plafonul apelului",status:"NV",cerut:"≤ "+fmtR(fi.sprijin_max),sursa:fi.sursa||"ghid",fix:"Completează sprijinul solicitat.",unde:"sec-fin"});
      else add({strat:"Financiar",titlu:"Sprijin ≤ plafonul apelului",status:sprR<=fi.sprijin_max?"CONFORM":"NECONFORM",blocant:sprR>fi.sprijin_max,gasit:fmtR(sprR),cerut:"≤ "+fmtR(fi.sprijin_max),sursa:fi.sursa||"ghid",fix:sprR>fi.sprijin_max?"Reduci sprijinul cu "+fmtR(sprR-fi.sprijin_max)+" (sau împarți investiția) — altfel cererea e respinsă administrativ.":"",unde:"sec-fin"}); }
    if(fi.sprijin_min!=null&&sprR!=null) add({strat:"Financiar",titlu:"Sprijin ≥ minimul apelului",status:sprR>=fi.sprijin_min?"CONFORM":"NECONFORM",blocant:sprR<fi.sprijin_min,gasit:fmtR(sprR),cerut:"≥ "+fmtR(fi.sprijin_min),sursa:fi.sursa||"ghid",fix:sprR<fi.sprijin_min?"Sprijinul e sub minimul apelului — crește valoarea proiectului sau alege alt apel.":"",unde:"sec-fin"});
    if(fi.intensitate_max_pct!=null){ if(it==null) add({strat:"Financiar",titlu:"Intensitatea sprijinului ≤ max",status:"NV",cerut:"≤ "+fi.intensitate_max_pct+"%",sursa:fi.sursa||"ghid",fix:"Completează valoarea proiectului și sprijinul.",unde:"sec-fin"});
      else add({strat:"Financiar",titlu:"Intensitatea sprijinului ≤ max",status:it<=fi.intensitate_max_pct?"CONFORM":"NECONFORM",blocant:it>fi.intensitate_max_pct,gasit:it+"%",cerut:"≤ "+fi.intensitate_max_pct+"%",sursa:fi.sursa||"ghid",fix:it>fi.intensitate_max_pct?"Crește cofinanțarea la cel puțin "+(100-fi.intensitate_max_pct)+"% din valoarea eligibilă.":"",unde:"sec-fin"}); }
    (fi.plafoane||[]).filter(p=>p.confirmat!==false&&p.categorie).forEach(p=>{ const ch=(fin.cheltuieli||[]).find(x=>String(x.categorie).trim().toLowerCase()===String(p.categorie).trim().toLowerCase());
      if(!ch){ add({strat:"Financiar",titlu:"Plafon: "+p.categorie,status:"NV",cerut:(p.tip==="pct"?"≤ "+p.val+"%":"≤ "+nf.format(p.val)),sursa:p.sursa||"ghid",fix:"Adaugă cheltuiala «"+p.categorie+"» în buget (sau 0 dacă nu există).",unde:"sec-fin"}); return; }
      const suma=evNum(ch.suma)||0; let ok,gasit,cerut; if(p.tip==="pct"){ const pct=val?Math.round(suma/val*1000)/10:null; ok=pct!=null&&pct<=p.val; gasit=(pct==null?"?":pct+"%"); cerut="≤ "+p.val+"%"; } else { ok=suma<=p.val; gasit=nf.format(suma); cerut="≤ "+nf.format(p.val); }
      add({strat:"Financiar",titlu:"Plafon: "+p.categorie,status:ok?"CONFORM":"NECONFORM",blocant:!ok,gasit,cerut,sursa:p.sursa||"ghid",fix:ok?"":"Categoria «"+p.categorie+"» depășește plafonul din ghid — redistribuie sau taie.",unde:"sec-fin"}); });
    (fi.neeligibile||[]).forEach(nl=>{ const nm=nl.categorie||nl; const ch=(fin.cheltuieli||[]).find(x=>String(x.categorie).trim().toLowerCase()===String(nm).trim().toLowerCase()); if(ch&&evNum(ch.suma)>0) add({strat:"Financiar",titlu:"Cheltuială neeligibilă în buget",status:"NECONFORM",blocant:true,gasit:nm,cerut:"absentă / trecută la neeligibile",sursa:nl.sursa||"ghid",fix:"Mută «"+nm+"» la cheltuieli neeligibile (finanțate de solicitant).",unde:"sec-fin"}); });
  }
  if(val!=null&&spr!=null){ if(cofIn==null) add({strat:"Financiar",titlu:"Sprijin + cofinanțare = valoare totală",status:"NV",cerut:nf.format(val),sursa:"aritmetică buget (clarificare tipică CAE)",fix:"Introdu cofinanțarea din buget (implicit "+nf.format(val-spr)+") ca să confirm compunerea sumelor.",unde:"sec-fin"}); else { const suma=spr+cofIn; const ok=Math.abs(suma-val)<=1; add({strat:"Financiar",titlu:"Sprijin + cofinanțare = valoare totală",status:ok?"CONFORM":"NECONFORM",blocant:false,gasit:nf.format(spr)+" + "+nf.format(cofIn)+" = "+nf.format(suma),cerut:nf.format(val),sursa:"aritmetică buget (clarificare tipică CAE)",fix:ok?"":"Sumele nu se compun — aliniază bugetul înainte de depunere.",unde:"sec-fin"}); } }
  if(spr!=null&&val!=null&&spr>val) add({strat:"Financiar",titlu:"Sprijinul depășește valoarea proiectului",status:"NECONFORM",blocant:true,gasit:nf.format(spr)+" > "+nf.format(val),cerut:"sprijin ≤ valoare",sursa:"aritmetică buget",fix:"Corectează valorile.",unde:"sec-fin"});

  /* ---- B. Reguli de eligibilitate adăugate manual din ghid ---- */
  (rb.eligibilitate||[]).forEach(c=>{ const lbl=(EV_FACTFIELDS.find(x=>x[0]===c.camp)||[])[1]||c.camp; const cerut=EV_OPLBL[c.op]+" "+c.val;
    if(c.confirmat===false){ add({strat:"Eligibilitate",titlu:lbl,status:"NV",cerut,sursa:c.sursa||"ghid",fix:"Regulă neconfirmată din ghid — confirmă-o în «Reguli avansate».",unde:"sec-sol"}); return; }
    const v=sol[c.camp]; if(v==null||v===""){ add({strat:"Eligibilitate",titlu:lbl,status:"NV",cerut,sursa:c.sursa||"ghid",fix:"Completează «"+lbl+"» la solicitant.",unde:"sec-sol"}); return; }
    const r=evCmp(c.op,v,c.val); if(r===null){ add({strat:"Eligibilitate",titlu:lbl,status:"NV",gasit:v,cerut,sursa:c.sursa||"ghid",unde:"sec-sol"}); return; }
    add({strat:"Eligibilitate",titlu:lbl,status:r?"CONFORM":"NECONFORM",blocant:!r,gasit:v,cerut,sursa:c.sursa||"ghid",fix:r?"":"Condiție de eligibilitate din ghid neîndeplinită.",unde:"sec-sol"}); });

  /* ---- C. Legislație transversală (universală, cu sursă) ---- */
  const leg=new Set(rb.legislatie||[]); const isPriv=!["UAT","ONG","institutie_publica","universitate"].includes(sol.tip||"privat");
  if(leg.has("dificultate")&&isPriv){ const cp=evNum(sol.capitaluri_proprii_lei); const v=evNum(sol.vechime_ani);
    if(cp==null) add({strat:"Legislație",titlu:"Întreprindere în dificultate",status:"NV",cerut:"capitaluri proprii ≥ 0",sursa:"Reg. (UE) 651/2014 art. 2 pct. 18",fix:"Completează capitalurile proprii din ultimul bilanț.",unde:"sec-sol"});
    else if(cp<0&&v!=null&&v<3) add({strat:"Legislație",titlu:"Întreprindere în dificultate",status:"CONFORM",gasit:nf.format(cp)+" lei · vechime "+v+" ani",cerut:"excepție <3 ani (fără insolvență)",sursa:"Reg. 651/2014 art. 2 pct. 18 lit. a)–c)",fix:"Excepția pentru firme sub 3 ani se aplică doar dacă nu e în insolvență — declară pe propria răspundere."});
    else add({strat:"Legislație",titlu:"Întreprindere în dificultate",status:cp>=0?"CONFORM":"NECONFORM",blocant:cp<0,gasit:nf.format(cp)+" lei",cerut:"capitaluri proprii ≥ 0",sursa:"Reg. (UE) 651/2014 art. 2 pct. 18 · checklist CAE",fix:cp<0?"Capitaluri proprii negative = criteriu eliminatoriu. Remediere înainte de depunere: majorare de capital / conversie creanțe / acoperire pierderi.":"",unde:"sec-sol"}); }
  if(leg.has("imm")&&isPriv){ const ang=evNum(sol.nr_angajati); const ca=evNum(sol.cifra_afaceri_lei); const calc=evImmCalc(ang,ca!=null?ca/curs:null);
    if(!sol.dimensiune) add({strat:"Legislație",titlu:"Încadrarea în categoria IMM",status:"NV",sursa:"Reg. 651/2014 Anexa I",fix:"Alege dimensiunea declarată a întreprinderii.",unde:"sec-sol"});
    else if(calc){ const ok=EV_DIMS.indexOf(sol.dimensiune)>=EV_DIMS.indexOf(calc); add({strat:"Legislație",titlu:"Încadrarea IMM e consistentă cu datele",status:ok?"CONFORM":"NECONFORM",blocant:false,gasit:"declarat: "+sol.dimensiune+" · din date: "+calc+(ang!=null?" ("+ang+" angajați":"")+(ca!=null?(ang!=null?", ":" (")+"CA "+money(ca,"lei")+")":(ang!=null?")":"")),cerut:"declarat ≥ calculat",sursa:"Reg. 651/2014 Anexa I (praguri: <10 / <50 / <250 angajați; 2 / 10 / 50 mil EUR)",fix:ok?"":"Datele indică o categorie mai mare decât cea declarată. Verifică întreprinderile legate/partenere și ultimele două exerciții — o încadrare greșită duce la respingere sau recuperare.",unde:"sec-sol"}); } }
  if(leg.has("minimis")){ const mu=evNum(sol.minimis_utilizat_eur); const sE=toEUR(spr);
    if(mu==null||sE==null) add({strat:"Legislație",titlu:"Plafon de minimis 300.000 € / 3 ani",status:"NV",sursa:"Reg. (UE) 2023/2831",fix:"Completează minimisul utilizat (€) de întreprinderea unică și sprijinul solicitat.",unde:"sec-sol"});
    else add({strat:"Legislație",titlu:"Plafon de minimis 300.000 € / 3 ani",status:(mu+sE)<=300000?"CONFORM":"NECONFORM",blocant:(mu+sE)>300000,gasit:nf.format(Math.round(mu))+" € utilizat + "+nf.format(Math.round(sE))+" € = "+nf.format(Math.round(mu+sE))+" €",cerut:"≤ 300.000 € (întreprindere unică)",sursa:"Reg. (UE) 2023/2831 art. 3 · RegAS",fix:(mu+sE)>300000?"Depășire cu "+nf.format(Math.round(mu+sE-300000))+" €. Reduci sprijinul sau aștepți ieșirea din fereastra de 3 ani a unui ajutor vechi. Verifică tot grupul în RegAS.":"",unde:"sec-sol"});
    const veh=(fin.cheltuieli||[]).find(c=>/vehicul|autoutilitar|camion|autovehicul|transport (rutier )?de? ?marf/i.test(c.categorie||"")&&evNum(c.suma)>0);
    if(veh) add({strat:"Legislație",titlu:"Interdicție minimis: vehicule pentru transport rutier de mărfuri",status:"NECONFORM",blocant:true,gasit:veh.categorie,cerut:"absentă din cheltuielile eligibile",sursa:"Reg. (UE) 2023/2831 art. 1 · REF minimis",fix:"Scoate vehiculul de transport marfă din cheltuielile eligibile (rămâne la neeligibile).",unde:"sec-fin"}); }
  if(leg.has("regional")){ const gb=sol.judet?gberIntensity(sol.judet):null;
    if(!gb||it==null) add({strat:"Legislație",titlu:"Intensitate ≤ plafon regional GBER pe județ",status:"NV",sursa:"Harta ajutoarelor regionale 2022–2027",fix:"Completează județul, valoarea proiectului și sprijinul.",unde:"sec-sol"});
    else { const big=sol.dimensiune==="mare"; const mij=sol.dimensiune==="mijlocie"; const plaf=big?gb.mari:(mij?Math.min(gb.mari+10,70):gb.imm); add({strat:"Legislație",titlu:"Intensitate ≤ plafon regional GBER ("+sol.judet+")",status:it<=plaf?"CONFORM":"NECONFORM",blocant:it>plaf,gasit:it+"%",cerut:"≤ "+plaf+"% ("+(big?"întreprindere mare":mij?"mijlocie +10pp":"micro/mică +20pp")+")",sursa:"Harta ajutoarelor regionale RO 2022–2027 · GBER art. 14",fix:it>plaf?"Intensitatea depășește plafonul regional pentru "+sol.judet+" — crește cofinanțarea.":"",unde:"sec-fin"}); }
    if(ans("neinceput")==="nu") add({strat:"Legislație",titlu:"Efect stimulativ (GBER art. 6)",status:"NECONFORM",blocant:true,gasit:"lucrările au început",cerut:"cererea depusă ÎNAINTE de începerea lucrărilor",sursa:"Reg. 651/2014 art. 6",fix:"Ajutorul regional nu se poate acorda pentru investiții începute înainte de depunere.",unde:"sec-cae"}); }

  /* ---- D. Checklist pre-CAE (răspunsuri Da/Nu/Nu știu) ---- */
  const q=(k,titlu,sursa,fixNu,blocant,extra)=>{ const v=ans(k); if(v==="na") return; if(v==="ns"){ add({strat:"Pre-CAE",titlu,status:"NV",sursa,fix:"Răspunde la întrebare în dosar (Da / Nu).",unde:"sec-cae"}); return; } add(Object.assign({strat:"Pre-CAE",titlu,status:v==="da"?"CONFORM":"NECONFORM",blocant:v==="nu"&&blocant,gasit:v==="da"?"da":"nu",cerut:"da",sursa,fix:v==="nu"?fixNu:"",unde:"sec-cae"},extra||{})); };
  if(f.data_onrc){ const d=Math.round((pd(dep)-pd(f.data_onrc))/86400000); add({strat:"Pre-CAE",titlu:"Certificat constatator ONRC ≤ 30 zile",status:d<=30&&d>=0?"CONFORM":"NECONFORM",blocant:d>30,gasit:"emis "+fmtD(f.data_onrc)+" ("+d+" zile la depunere)",cerut:"≤ 30 zile",sursa:"checklist CAE (uzual în ghiduri)",fix:d>30?"Cere un certificat constatator nou înainte de depunere.":"",unde:"sec-cae"}); }
  else add({strat:"Pre-CAE",titlu:"Certificat constatator ONRC ≤ 30 zile",status:"NV",sursa:"checklist CAE",fix:"Introdu data emiterii certificatului constatator.",unde:"sec-cae"});
  q("declaratie","Declarația unică semnată de reprezentantul legal","checklist CAE (nu împuternicit, decât unde ghidul permite)","Semnătura împuternicitului e motiv frecvent de respingere — resemnează cu reprezentantul legal.",true);
  q("caen","Cod CAEN autorizat la locația de implementare","checklist CAE · L. 359/2004 (autorizare ONRC)","Autorizează CAEN-ul proiectului la sediul/punctul de lucru din proiect (ONRC, ~3 zile) înainte de depunere.",true);
  q("datorii","Fără datorii restante la bugetul de stat și local","checklist CAE · certificate de atestare fiscală","Achită sau eșalonează datoriile și obține certificate curate înainte de depunere.",true);
  q("imobil","Drepturi reale asupra imobilului, fără sarcini","checklist CAE · durabilitate art. 65 Reg. 2021/1060","Clarifică titlul (proprietate / concesiune / închiriere pe durata proiectului + durabilitate) și radiază sarcinile incompatibile.",true);
  if(!leg.has("regional")) q("neinceput","Investiția NU a început înainte de depunere","checklist CAE · efect stimulativ","Cheltuielile angajate înainte de depunere sunt de regulă neeligibile; unele apeluri resping proiectul.",true);
  q("profit","Profit din exploatare pozitiv (unde ghidul o cere)","checklist CAE — condiție prezentă doar în unele ghiduri","Verifică dacă ghidul cere profit din exploatare; dacă da, depunerea nu e posibilă pe acest exercițiu.",false);

  /* ---- E. Documente ---- */
  const prez=new Set((f.documente_prezente||[]).map(x=>String(x).trim().toLowerCase()));
  (rb.documente||[]).forEach(d=>{ if(!d.nume) return; const has=prez.has(String(d.nume).trim().toLowerCase());
    if(has) add({strat:"Documente",titlu:d.nume,status:"CONFORM",gasit:"prezent",cerut:"prezent"+(d.forma?" ("+d.forma+")":""),sursa:d.sursa||"ghid"});
    else if(d.confirmat!==false) add({strat:"Documente",titlu:d.nume,status:"NECONFORM",blocant:true,gasit:"lipsă",cerut:"obligatoriu"+(d.forma?" ("+d.forma+")":""),sursa:d.sursa||"ghid",fix:"Adaugă documentul «"+d.nume+"» în dosar.",unde:"sec-doc"});
    else add({strat:"Documente",titlu:d.nume,status:"NV",gasit:"nebifat",cerut:"de confirmat în ghid",sursa:d.sursa||"listă tipică",fix:"Bifează dacă e în dosar; confirmă în ghid dacă e obligatoriu.",unde:"sec-doc"}); });

  /* ---- F. Concordanțe ---- */
  const cc=f.concordanta||{};
  const pair=(k,label)=>{ const x=cc[k+"_cerere"], y=cc[k+"_buget"]; if((x==null||x==="")&&(y==null||y==="")) return; if(x==null||x===""||y==null||y===""){ add({strat:"Concordanță",titlu:label,status:"NV",sursa:"concordanță documente",fix:"Completează «"+label+"» din ambele documente.",unde:"sec-con"}); return; } const ok=String(x).replace(/\s|^RO/i,"").toLowerCase()===String(y).replace(/\s|^RO/i,"").toLowerCase(); add({strat:"Concordanță",titlu:label,status:ok?"CONFORM":"NECONFORM",blocant:false,gasit:x+" vs "+y,cerut:"identic",sursa:"cerere vs buget/anexe",fix:ok?"":"Clarificare probabilă: «"+label+"» diferă între documente.",unde:"sec-con"}); };
  pair("cui","CUI solicitant"); pair("denumire","Denumire solicitant");
  (cc.indicatori||[]).forEach(ind=>{ const vs=[ind.cerere,ind.buget,ind.anexa].filter(x=>x!=null&&x!==""); if(vs.length<2) return; const allEq=vs.every(x=>String(x).trim()===String(vs[0]).trim()); add({strat:"Concordanță",titlu:"Indicator: "+(ind.nume||"—"),status:allEq?"CONFORM":"NECONFORM",gasit:vs.join(" / "),cerut:"identic în toate documentele",sursa:"triplă concordanță",fix:allEq?"":"Aliniază indicatorul «"+ind.nume+"» în cerere / buget / anexe.",unde:"sec-con"}); });

  /* ---- G. Grila ---- */
  let gmin=0,gmax=0; const gcrit=[];
  (rb.grila&&rb.grila.criterii||[]).forEach(cr=>{ const pmax=evNum(cr.punctaj_max)||0; gmax+=pmax; let got=0; if(cr.tip==="obiectiv"&&cr.confirmat!==false&&cr.camp&&cr.op){ const v=sol[cr.camp]!=null?sol[cr.camp]:fin[cr.camp]; if(v!=null&&v!==""){ if(evCmp(cr.op,v,cr.val)) got=pmax; } } gmin+=got; gcrit.push({nume:cr.nume,pmax,got,tip:cr.tip,elim:cr.eliminatoriu}); });
  const prag=evNum(rb.grila&&rb.grila.prag_minim);
  if(prag!=null&&gmax>0&&gmin<prag) add({strat:"Grilă",titlu:"Prag de calificare",status:"NECONFORM",blocant:false,gasit:"punctaj garantat "+gmin,cerut:"≥ "+prag,sursa:"grilă ETF (ghid)",fix:"Sub prag pe criteriile obiective — punctele lipsă trebuie câștigate pe criteriile de apreciere: argumentează-le explicit în cerere.",unde:"sec-ctx"});

  /* ---- Sinteză ---- */
  const blocante=checks.filter(c=>c.blocant&&c.status==="NECONFORM");
  const clarificari=checks.filter(c=>c.strat==="Concordanță"&&c.status==="NECONFORM");
  const avert=checks.filter(c=>!c.blocant&&c.status==="NECONFORM"&&c.strat!=="Concordanță");
  const nv=checks.filter(c=>c.status==="NV"); const ok=checks.filter(c=>c.status==="CONFORM");
  let verdict,vclass;
  if(blocante.length){ verdict="NU se poate depune — "+blocante.length+" blocant"+(blocante.length>1?"e":"")+" de rezolvat"; vclass="no"; }
  else if(clarificari.length||avert.length){ verdict="Se poate depune CU RISCURI — "+(clarificari.length+avert.length)+" de remediat / clarificat"; vclass="warn"; }
  else if(nv.length){ verdict="Nicio neconformitate găsită — "+nv.length+" verificări incomplete"; vclass="warn"; }
  else { verdict="Se poate depune — toate regulile verificate sunt conforme"; vclass="go"; }
  const auto=checks.filter(c=>/radar/.test(c.sursa||"")).length, univ=checks.filter(c=>["Legislație","Pre-CAE"].includes(c.strat)).length, man=checks.filter(c=>c.strat==="Eligibilitate"&&!/radar/.test(c.sursa||"")).length;
  return { verdict,vclass,checks,blocante,clarificari,avert,nv,ok,grila:{min:gmin,max:gmax,prag,criterii:gcrit},meta:{auto,univ,man,total:checks.length,intensitate:it,cof,valoare:val,sprijin:spr} };
}

/* ============ UI ============ */
function evGetRb(){ return window.EVAL.rb[window.evUI.curId]||null; }
function evSet(path,val){ const p=path.split("."); let o=window.evUI; for(let i=0;i<p.length-1;i++){ if(o[p[i]]==null) o[p[i]]={}; o=o[p[i]]; } o[p[p.length-1]]=val; }
function evF(path,val){ evSet(path,val); evLive(); evSaveUI(); }
function evAns(k,v){ window.evUI.dosar.raspunsuri[k]=v; evRefresh("sec-cae"); evSaveUI(); }
function evSetRb(path,val){ const rb=evGetRb(); if(!rb) return; const p=path.split("."); let o=rb; for(let i=0;i<p.length-1;i++){ if(o[p[i]]==null) o[p[i]]={}; o=o[p[i]]; } const last=p[p.length-1]; o[last]=(val===""?null:(typeof val==="string"&&/^-?\d+(\.\d+)?$/.test(val)?parseFloat(val):val)); evSave(); evLive(); }
function evStep(n){ window.evUI.step=Math.max(0,Math.min(2,n|0)); evSaveUI(); render(); }
function evChooseClient(cid){ const D=window.evUI.dosar; D.client_id=cid; D.project_id=""; D.solicitant={}; D.concordanta={indicatori:[]}; if(cid) evFillFromCRM(); evSaveUI(); render(); }
function evChooseProject(pid){ const D=window.evUI.dosar; D.project_id=pid; const p=PR.find(x=>x.id===pid); if(p){ if(p.client_id&&p.client_id!==D.client_id){ D.client_id=p.client_id; D.solicitant={}; D.concordanta={indicatori:[]}; } if(p.apel_id&&apelById(p.apel_id)) evChooseApel(p.apel_id,true); } evFillFromCRM(); evSaveUI(); render(); }
function evChooseApel(aid,silent){ if(!aid){ window.evUI.curId=null; evSaveUI(); if(!silent) render(); return; } const rb=evRbForApel(aid); window.evUI.curId=rb.id; evSaveUI(); if(!silent) render(); }
function evFromFinanciar(){ if(typeof finState!=="function"||typeof calcBil!=="function"){ toast("Modulul Financiar nu e disponibil"); return; } const f=finState(); const s=window.evUI.dosar.solicitant; const cp=calcBil(2).capProprii; const ca=f.p.ca[2], ang=f.p.angajati[2]; let n=0; if(ca){ s.cifra_afaceri_lei=ca; n++; } if(ang){ s.nr_angajati=ang; n++; } if(f.b.capVarsat[2]||f.b.exProfit[2]||f.b.exPierdere[2]||f.b.rezerve[2]){ s.capitaluri_proprii_lei=Math.round(cp); n++; } if(!n){ toast("Fișa Financiar e goală — completează Bilanțul (anul "+f.ani[2]+")"); return; } evRefresh("sec-sol"); evSaveUI(); toast("Preluat din Financiar (anul "+f.ani[2]+"): "+n+" câmpuri"); }
function evImport(){ const i=document.createElement("input"); i.type="file"; i.accept=".json,application/json"; i.onchange=ev=>{ const f=ev.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ try{ const o=JSON.parse(r.result); if(!o.dosar) throw new Error("nu e un raport de verificare exportat de aici"); window.evUI.dosar=Object.assign(evEmptyDosar(),o.dosar); if(o.apel_id&&apelById(o.apel_id)) evChooseApel(o.apel_id,true); else if(o.apel){ const rb=evList().find(x=>x.titlu===o.apel); if(rb) window.evUI.curId=rb.id; } window.evUI.step=1; evSaveUI(); render(); toast("Dosar încărcat"); }catch(err){ toast("Fișier invalid: "+err.message); } }; r.readAsText(f); }; i.click(); }
function evPick(id){ window.evUI.curId=id; render(); }
function evDelRb(){ const rb=evGetRb(); if(!rb) return; if(!confirm("Ștergi regulile salvate pentru «"+rb.titlu+"»?")) return; delete window.EVAL.rb[window.evUI.curId]; window.evUI.curId=null; evSave(); render(); }
function evResetDosar(){ if(!confirm("Golești dosarul curent?")) return; window.evUI.dosar=evEmptyDosar(); render(); }
function evStartFor(pid){ window.evUI.dosar=evEmptyDosar(); S.view="verif"; window.evUI.step=0; closeDrawer(); evChooseProject(pid); if(window.evUI.curId) window.evUI.step=1; render(); }
function evFillFromCRM(){ const D=window.evUI.dosar, s=D.solicitant, fn=D.financiar, cc=D.concordanta; const c=D.client_id?clientById(D.client_id):null; const p=D.project_id?PR.find(x=>x.id===D.project_id):null;
  if(c){ const df=c.date_financiare||{}; s.dimensiune=c.dimensiune||s.dimensiune||""; s.tip=c.tip||s.tip||"privat"; s.judet=c.judet||s.judet||""; s.regiune=c.regiune||s.regiune||""; s.caen=c.caen_principal||s.caen||"";
    if(c.an_infiintare) s.vechime_ani=TODAY.getFullYear()-c.an_infiintare; if(df.capitaluri_proprii_lei!=null) s.capitaluri_proprii_lei=df.capitaluri_proprii_lei; if(df.cifra_afaceri_3ani_lei) s.cifra_afaceri_lei=Object.values(df.cifra_afaceri_3ani_lei).pop(); if(df.nr_angajati!=null) s.nr_angajati=df.nr_angajati; else if(c.angajati!=null) s.nr_angajati=c.angajati;
    const mu=(c.ajutoare_minimis||[]).reduce((a,x)=>a+(x.suma_eur||0),0); s.minimis_utilizat_eur=mu||0; if(c.datorii_fiscale!=null) D.raspunsuri.datorii=c.datorii_fiscale?"nu":"da";
    cc.cui_cerere=c.cui||""; cc.cui_buget=c.cui||""; cc.denumire_cerere=c.denumire||""; cc.denumire_buget=c.denumire||""; }
  if(p){ fn.moneda="lei"; if(p.valoare_totala_lei!=null) fn.valoare_proiect=p.valoare_totala_lei; if(p.grant_lei!=null) fn.sprijin_solicitat=p.grant_lei; if(p.cofinantare_lei!=null) fn.cofinantare=p.cofinantare_lei; } }

/* ---- semafor live ---- */
function evLive(){ const rb=evGetRb(); const el=document.getElementById("evSemafor"); if(!rb){ if(el) el.innerHTML=""; return null; } const rep=evEvaluate(rb,window.evUI.dosar); window.evUI.report=rep; if(el) el.innerHTML=evSemaforHtml(rep); const r=document.getElementById("evReport"); if(r) r.innerHTML=evReportHtml(rep); ["sec-sol","sec-fin","sec-cae","sec-doc","sec-con"].forEach(id=>{ const b=document.getElementById(id+"-prog"); if(b) b.innerHTML=evProgBadge(id,rep); }); return rep; }
function evProgBadge(sec,rep){ const cs=rep.checks.filter(c=>c.unde===sec||(sec==="sec-doc"&&c.strat==="Documente")||(sec==="sec-con"&&c.strat==="Concordanță")); const bad=cs.filter(c=>c.status==="NECONFORM").length, nv=cs.filter(c=>c.status==="NV").length; if(!cs.length) return ''; if(bad) return '<span class="cd cd-crit">'+bad+' de rezolvat</span>'; if(nv) return '<span class="cd cd-warn">'+nv+' de completat</span>'; return '<span class="cd cd-good">complet ✓</span>'; }
function evSemaforHtml(rep){ const pill=(n,l,cls)=>'<span class="cd '+(n?cls:"cd-off")+'">'+n+' '+l+'</span>'; const g=rep.grila;
  return '<span class="evverdict-mini '+rep.vclass+'">'+esc(rep.verdict.split(" — ")[0])+'</span>'+pill(rep.blocante.length,"blocante","cd-crit")+pill(rep.clarificari.length+rep.avert.length,"de remediat","cd-warn")+pill(rep.nv.length,"neverificate","cd-off")+'<span class="hide-m">'+pill(rep.ok.length,"conforme","cd-good")+'</span>'+(g.max?'<span class="cd cd-off hide-m">punctaj '+g.min+'–'+g.max+(g.prag!=null?' / prag '+g.prag:'')+'</span>':"")+(rep.meta.intensitate!=null?'<span class="cd cd-off hide-m">intensitate '+rep.meta.intensitate+'%</span>':"")+'<span style="flex:1"></span>'+(window.evUI.step<2?'<button class="btn small" onclick="evStep(2)">Raport →</button>':'<button class="btn small" onclick="evStep(1)">← Dosar</button>'); }
function evRefresh(secId){ const el=document.getElementById(secId); if(el){ const tmp=document.createElement("div"); tmp.innerHTML=evSectionHtml(secId); el.replaceWith(tmp.firstElementChild); } evLive(); }
function evJump(sec){ if(window.evUI.step!==1){ window.evUI.step=1; render(); } setTimeout(()=>{ const el=document.getElementById(sec); if(el){ el.scrollIntoView({behavior:"smooth",block:"start"}); el.classList.add("evflash"); setTimeout(()=>el.classList.remove("evflash"),1400); } },60); }

/* ---- pas 0: context & reguli ---- */
function evRuleSentences(rb){ const a=rb.apel_id?(apelById(rb.apel_id)||{}):{}; const out=[]; const fi=rb.financiar||{}; const src=rb.auto_conf===false?"radar · [DE VERIFICAT]":"radar";
  if(a.id_apel){ if((a.tip_beneficiar||[]).length) out.push({t:"Solicitanți eligibili: "+a.tip_beneficiar.map(b=>BEN[b]||b).join(", "),s:src}); if((a.judete_eligibile||[]).length) out.push({t:"Doar județele: "+a.judete_eligibile.join(", "),s:src}); else if((a.regiuni||[]).length) out.push({t:"Teritoriu: "+a.regiuni.join(", "),s:src}); if(a.data_inchidere) out.push({t:"Termen de depunere: "+fmtD(a.data_inchidere),s:src}); }
  if(fi.sprijin_min!=null||fi.sprijin_max!=null) out.push({t:"Sprijin "+(fi.sprijin_min!=null?"≥ "+nf.format(fi.sprijin_min)+" ":"")+(fi.sprijin_max!=null?"≤ "+nf.format(fi.sprijin_max)+" ":"")+(fi.moneda||"EUR"),s:fi.sursa||"ghid"});
  if(fi.intensitate_max_pct!=null) out.push({t:"Intensitate maximă "+fi.intensitate_max_pct+"% (cofinanțare ≥ "+(100-fi.intensitate_max_pct)+"%)",s:fi.sursa||"ghid"});
  if(fi.tip_ajutor==="minimis") out.push({t:"Ajutor de minimis → plafon 300.000 € / 3 ani pe întreprindere unică; interzis pentru vehicule de transport marfă",s:"Reg. 2023/2831"}); if(fi.tip_ajutor==="stat") out.push({t:"Ajutor de stat regional → intensitate plafonată pe județ (harta 2022–2027), efect stimulativ",s:"GBER art. 6, 14"});
  (rb.eligibilitate||[]).forEach(c=>out.push({t:((EV_FACTFIELDS.find(x=>x[0]===c.camp)||[])[1]||c.camp)+" "+EV_OPLBL[c.op]+" "+c.val,s:c.sursa||"ghid",man:true,conf:c.confirmat!==false}));
  (fi.plafoane||[]).forEach(p=>out.push({t:"Plafon «"+p.categorie+"» ≤ "+p.val+(p.tip==="pct"?"%":""),s:p.sursa||"ghid",man:true}));
  (fi.neeligibile||[]).forEach(n=>out.push({t:"Neeligibil: "+(n.categorie||n),s:n.sursa||"ghid",man:true}));
  const leg=rb.legislatie||[]; if(leg.includes("dificultate")) out.push({t:"Nu întreprindere în dificultate (capitaluri proprii ≥ 0; excepție <3 ani)",s:"Reg. 651/2014 art. 2 pct. 18"}); if(leg.includes("imm")) out.push({t:"Încadrarea IMM verificată față de angajați și cifra de afaceri",s:"Reg. 651/2014 Anexa I"});
  out.push({t:"Checklist pre-CAE: ONRC ≤30 zile, declarație semnată de reprezentantul legal, CAEN autorizat, fără datorii, drepturi asupra imobilului, investiție neîncepută",s:"referențial Conformitate"});
  out.push({t:(rb.documente||[]).length+" documente în lista dosarului ("+(rb.documente||[]).filter(d=>d.confirmat!==false).length+" confirmate obligatorii)",s:"ghid / listă tipică"});
  return out; }
function evContextCard(){ const D=window.evUI.dosar; const rb=evGetRb(); const cli=CL; const prj=PR.filter(p=>!D.client_id||p.client_id===D.client_id);
  let h='<div class="card" id="sec-ctx">'+cardHead('Pentru cine și pentru ce verific?')+'<div class="evform"><div class="r3">';
  h+='<div><label>Client (din CRM)</label><select onchange="evChooseClient(this.value)"><option value="">— fără client / manual —</option>'+cli.map(c=>'<option value="'+esc(c.id)+'"'+(D.client_id===c.id?" selected":"")+'>'+esc(c.denumire)+(c.demo?" (demo)":"")+'</option>').join("")+'</select></div>';
  h+='<div><label>Proiect (opțional)</label><select onchange="evChooseProject(this.value)"><option value="">— fără proiect —</option>'+prj.map(p=>'<option value="'+esc(p.id)+'"'+(D.project_id===p.id?" selected":"")+'>'+esc(p.titlu)+'</option>').join("")+'</select></div>';
  const groups={}; A.filter(a=>a.stare!=="inchis").forEach(a=>{ (groups[a.program||"Alte programe"]=groups[a.program||"Alte programe"]||[]).push(a); });
  h+='<div><label>Apelul de finanțare</label><select onchange="evChooseApel(this.value)"><option value="">— alege apelul —</option>'+Object.keys(groups).sort((x,y)=>x.localeCompare(y,"ro")).map(g=>'<optgroup label="'+esc(g)+'">'+groups[g].map(a=>'<option value="'+esc(a.id_apel)+'"'+(rb&&rb.apel_id===a.id_apel?" selected":"")+'>'+esc((a.titlu||"Apel").slice(0,70))+(a.data_inchidere?' · '+fmtDs(a.data_inchidere):'')+'</option>').join("")+'</optgroup>').join("")+'</select></div></div>';
  h+='<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px"><span class="evsrc">Alege apelul și regulile se încarcă singure din radar (verificat la sursă) + legislația aplicabilă. Clientul precompletează dosarul.</span>'+(!rb?'<button class="btn small" onclick="window.evUI.curId=evRbForApel(\'\').id;evSaveUI();render()">Verificare generală, fără apel →</button>':'')+'<button class="btn small ghost" onclick="evImport()" title="continuă un dosar exportat (JSON)">⬆ Încarcă dosar</button></div>';
  h+='</div></div>';
  if(rb){ const rules=evRuleSentences(rb); const a=rb.apel_id?apelById(rb.apel_id):null;
    h+='<div class="card section" style="margin-top:14px">'+cardHead('Regulile după care verific'+(a?' — '+esc(a.program||""):''),rules.length,'<span class="evsrc">'+(rb.auto?'reguli pre-încărcate din radar':'reguli adăugate manual')+'</span>');
    if(rb.auto_conf===false) h+='<div class="callout warn">Apelul e marcat <b>[DE VERIFICAT]</b> în radar — regulile preluate automat pot fi incomplete. Confirmă-le cu ghidul.</div>';
    h+='<ul class="evrules">'+rules.map(r=>'<li><span class="evdot'+(r.man&&r.conf===false?" nv":"")+'"></span><span>'+esc(r.t)+'</span><span class="evsrc">'+esc(r.s)+'</span></li>').join("")+'</ul>';
    h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn small" onclick="evOpenAdvanced()">⚙ Reguli avansate din ghid (plafoane, documente, grilă)</button>'+(a&&a.url_ghid?'<a class="btn small" href="'+esc(a.url_ghid)+'" target="_blank">📄 Ghidul solicitantului ↗</a>':'')+(a&&a.url_sursa?'<a class="btn small" href="'+esc(a.url_sursa)+'" target="_blank">🔗 Sursa apelului ↗</a>':'')+'<button class="btn small ghost" onclick="evDelRb()">🗑 șterge regulile</button></div>';
    h+='</div>'; }
  const rbs=evList().filter(r=>!rb||r.id!==rb.id); if(rbs.length) h+='<div class="evsrc" style="margin-top:10px">Reguli salvate anterior: '+rbs.map(r=>'<button class="fchip" onclick="evPick(\''+r.id+'\')">'+esc((r.titlu||"apel").slice(0,36))+'</button>').join(" ")+'</div>';
  return h; }

