function evTri(k,opts){ const v=(window.evUI.dosar.raspunsuri||{})[k]||"ns"; const o=[["da","Da"],["nu","Nu"]].concat(opts&&opts.na?[["na","Nu e cazul"]]:[]).concat([["ns","Nu știu"]]); return '<span class="tri'+(v==="ns"?" unanswered":"")+'">'+o.map(([x,l])=>'<button class="'+x+(v===x?" on":"")+'" onclick="evAns(\''+k+'\',\''+x+'\')">'+l+'</button>').join("")+'</span>'; }
